import{_ as a,o as t,c as s,ah as i}from"./chunks/framework.Sdx4l2LO.js";const u=JSON.parse('{"title":"Specifications","description":"","frontmatter":{},"headers":[],"relativePath":"specs/index.md","filePath":"specs/index.md","lastUpdated":1774801192000}'),n={name:"specs/index.md"};function o(r,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="specifications" tabindex="-1">Specifications <a class="header-anchor" href="#specifications" aria-label="Permalink to &quot;Specifications&quot;">​</a></h1><p>Welcome to the DINOForge specifications documentation. This section contains comprehensive user and technical documentation for the DINOForge platform.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>DINOForge specifications are divided into two primary documents:</p><h3 id="user-specification" tabindex="-1"><a href="./user-spec">User Specification</a> <a class="header-anchor" href="#user-specification" aria-label="Permalink to &quot;[User Specification](./user-spec.md)&quot;">​</a></h3><p><strong>For</strong>: Modders, game enthusiasts, content creators</p><p><strong>Contains</strong>:</p><ul><li>User personas and target audiences</li><li>Core user workflows (install, create pack, balance tune, hot reload)</li><li>Feature specifications for each DINOForge capability</li><li>Implementation status and known issues</li><li>Performance expectations</li><li>Installation and pack creation workflows</li><li>Acceptance testing checklists</li></ul><p><strong>Use This If</strong>:</p><ul><li>You want to create a mod for DINO</li><li>You need to understand what DINOForge can do</li><li>You&#39;re testing a pack and need acceptance criteria</li><li>You want to know about known limitations</li></ul><hr><h3 id="technical-specification" tabindex="-1"><a href="./technical-spec">Technical Specification</a> <a class="header-anchor" href="#technical-specification" aria-label="Permalink to &quot;[Technical Specification](./technical-spec.md)&quot;">​</a></h3><p><strong>For</strong>: Plugin developers, runtime maintainers, advanced modders</p><p><strong>Contains</strong>:</p><ul><li>Architecture overview (three-layer design)</li><li>Core component responsibilities (Plugin, RuntimeDriver, KeyInputSystem, ModPlatform, DebugOverlay, HudStrip)</li><li>ECS Bridge layer (ComponentMap, EntityQueries, AssetSwapSystem)</li><li>Key design decisions and their rationale</li><li>Critical facts about DINO&#39;s ECS (prefab entities, scene transitions, two-boot cycle)</li><li>Component interactions and data flow diagrams</li><li>F9/F10 key input architecture</li><li>Pack system and registry pattern</li><li>Schema validation pipeline</li><li>Technical constraints and workarounds</li><li>Extension points for custom plugins</li></ul><p><strong>Use This If</strong>:</p><ul><li>You want to extend DINOForge with custom domains</li><li>You need to understand internal architecture</li><li>You&#39;re debugging integration issues</li><li>You&#39;re contributing to the runtime or SDK</li></ul><hr><h2 id="quick-navigation" tabindex="-1">Quick Navigation <a class="header-anchor" href="#quick-navigation" aria-label="Permalink to &quot;Quick Navigation&quot;">​</a></h2><h3 id="for-modders" tabindex="-1">For Modders <a class="header-anchor" href="#for-modders" aria-label="Permalink to &quot;For Modders&quot;">​</a></h3><ol><li><strong>Getting Started</strong>: Read <a href="./user-spec#5-installation-workflow">User Specification - Installation Workflow</a></li><li><strong>Create Your First Pack</strong>: See <a href="./user-spec#6-pack-creation-workflow">User Specification - Pack Creation Workflow</a></li><li><strong>Debug Issues</strong>: Check <a href="./user-spec#7-common-workflows">User Specification - Common Workflows</a></li><li><strong>Known Issues</strong>: Review <a href="./user-spec#8-known-issues-and-limitations">User Specification - Known Issues and Limitations</a></li></ol><h3 id="for-plugin-developers" tabindex="-1">For Plugin Developers <a class="header-anchor" href="#for-plugin-developers" aria-label="Permalink to &quot;For Plugin Developers&quot;">​</a></h3><ol><li><strong>Understand Architecture</strong>: Read <a href="./technical-spec#1-architecture-overview">Technical Specification - Architecture Overview</a></li><li><strong>Learn Core Components</strong>: Study <a href="./technical-spec#2-core-components">Technical Specification - Core Components</a></li><li><strong>Understand Design Decisions</strong>: Review <a href="./technical-spec#3-key-design-decisions">Technical Specification - Key Design Decisions</a></li><li><strong>Learn Extension Points</strong>: See <a href="./technical-spec#11-extension-points-for-plugin-developers">Technical Specification - Extension Points</a></li></ol><hr><h2 id="feature-status-matrix" tabindex="-1">Feature Status Matrix <a class="header-anchor" href="#feature-status-matrix" aria-label="Permalink to &quot;Feature Status Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>User-Facing</th><th>Tech Details</th><th>Status</th><th>Version</th></tr></thead><tbody><tr><td>Pack loading &amp; manifest system</td><td><a href="./user-spec#f1-pack-loading--manifest-system">User</a></td><td><a href="./technical-spec#27-pack-system-architecture">Tech</a></td><td>✅ STABLE</td><td>0.5.0+</td></tr><tr><td>Debug overlay (F9)</td><td><a href="./user-spec#story-2-view-debug-overlay-f9-key">User</a></td><td><a href="./technical-spec#25-debugoverlaycs-f9-display">Tech</a></td><td>✅ STABLE</td><td>0.6.0+</td></tr><tr><td>Mod menu (F10)</td><td><a href="./user-spec#story-3-access-in-game-mod-menu-f10-key">User</a></td><td><a href="./technical-spec#26-hudstripcs-f10-display">Tech</a></td><td>✅ STABLE</td><td>0.8.0+</td></tr><tr><td>Hot reload (YAML)</td><td><a href="./user-spec#story-7-hot-reload-packs-without-restarting-game">User</a></td><td><a href="./technical-spec#flow-3-f10-pressed--reload">Tech</a></td><td>✅ STABLE</td><td>0.9.0+</td></tr><tr><td>Asset swap system</td><td><a href="./user-spec#story-6-load-themed-asset-packs">User</a></td><td><a href="./technical-spec#assetsswapsystem">Tech</a></td><td>✅ STABLE</td><td>0.7.0+</td></tr><tr><td>Desktop Companion</td><td><a href="./user-spec#story-9-use-desktop-companion-to-manage-packs">User</a></td><td><a href="./technical-spec#extension-point-2-custom-asset-processor">Tech</a></td><td>✅ STABLE</td><td>0.9.0+</td></tr><tr><td>Warfare domain plugin</td><td><a href="./user-spec#story-10-create-a-total-conversion">User</a></td><td><a href="./technical-spec#extension-point-1-custom-domain-plugin">Tech</a></td><td>✅ STABLE</td><td>0.6.0+</td></tr></tbody></table><hr><h2 id="architecture-diagram" tabindex="-1">Architecture Diagram <a class="header-anchor" href="#architecture-diagram" aria-label="Permalink to &quot;Architecture Diagram&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ CONTENT LAYER (Packs)                           │</span></span>
<span class="line"><span>│  YAML manifests, assets, registries             │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span>
<span class="line"><span>           ↑</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ SDK LAYER                                       │</span></span>
<span class="line"><span>│  ContentLoader, Registry, Schemas, Validators  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span>
<span class="line"><span>           ↑</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ RUNTIME LAYER (BepInEx Plugin)                  │</span></span>
<span class="line"><span>│  Plugin.cs → RuntimeDriver → Systems            │</span></span>
<span class="line"><span>│  • KeyInputSystem (F9/F10)                      │</span></span>
<span class="line"><span>│  • ModPlatform (orchestration)                  │</span></span>
<span class="line"><span>│  • DebugOverlay &amp; HudStrip (UI)                │</span></span>
<span class="line"><span>│  • ECS Bridge (ComponentMap, EntityQueries)    │</span></span>
<span class="line"><span>│  • AssetSwapSystem (visuals)                    │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span>
<span class="line"><span>           ↑</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ GAME (DINO)                                     │</span></span>
<span class="line"><span>│  Unity 2021.3.45f2 ECS + BepInEx                │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="key-facts" tabindex="-1">Key Facts <a class="header-anchor" href="#key-facts" aria-label="Permalink to &quot;Key Facts&quot;">​</a></h2><h3 id="for-users" tabindex="-1">For Users <a class="header-anchor" href="#for-users" aria-label="Permalink to &quot;For Users&quot;">​</a></h3><ul><li><strong>Two Overlays</strong>: F9 (debug) and F10 (mod menu) are always available</li><li><strong>Hot Reload</strong>: Edit YAML, save, and see changes in-game without restart</li><li><strong>Asset Swaps</strong>: Pack authors can include custom 3D models for units/buildings</li><li><strong>No Crashes on Errors</strong>: Missing assets or broken configs fail gracefully with fallbacks</li><li><strong>Performance</strong>: &lt;2ms overhead per overlay; full game at 60 FPS with mods</li></ul><h3 id="for-developers" tabindex="-1">For Developers <a class="header-anchor" href="#for-developers" aria-label="Permalink to &quot;For Developers&quot;">​</a></h3><ul><li><strong>ECS First</strong>: All core systems are ECS-based, not MonoBehaviour-based</li><li><strong>Persistence</strong>: RuntimeDriver persists across scene transitions via DontDestroyOnLoad</li><li><strong>Win32 Input</strong>: F9/F10 work globally via GetAsyncKeyState (not Unity Input)</li><li><strong>Prefab Entities</strong>: All DINO entities use <code>EntityQueryOptions.IncludePrefab</code></li><li><strong>600-Frame Stabilization</strong>: Asset swaps wait 600 frames before executing</li></ul><hr><h2 id="troubleshooting-checklist" tabindex="-1">Troubleshooting Checklist <a class="header-anchor" href="#troubleshooting-checklist" aria-label="Permalink to &quot;Troubleshooting Checklist&quot;">​</a></h2><h3 id="pack-won-t-load" tabindex="-1">Pack Won&#39;t Load <a class="header-anchor" href="#pack-won-t-load" aria-label="Permalink to &quot;Pack Won&#39;t Load&quot;">​</a></h3><ol><li><strong>Validate manifest</strong>: Run <code>dotnet run --project src/Tools/PackCompiler -- validate packs/my-pack</code></li><li><strong>Check schema</strong>: Ensure all YAML files match canonical schemas in <code>schemas/</code></li><li><strong>Check dependencies</strong>: Verify all packs in <code>depends_on</code> are installed</li><li><strong>Check conflicts</strong>: Review <code>conflicts_with</code> list; remove if conflicting pack is installed</li></ol><h3 id="assets-not-showing" tabindex="-1">Assets Not Showing <a class="header-anchor" href="#assets-not-showing" aria-label="Permalink to &quot;Assets Not Showing&quot;">​</a></h3><ol><li><strong>Check bundle filename</strong>: Must match exactly the <code>visual_asset</code> ID in pack YAML</li><li><strong>Check Unity version</strong>: Bundles must be built with Unity 2021.3.45f2</li><li><strong>Check addressables</strong>: Verify bundle is registered in addressables catalog</li><li><strong>Check logs</strong>: Press F9 and look for &quot;AssetSwap&quot; warnings in error log</li></ol><h3 id="hot-reload-not-working" tabindex="-1">Hot Reload Not Working <a class="header-anchor" href="#hot-reload-not-working" aria-label="Permalink to &quot;Hot Reload Not Working&quot;">​</a></h3><ol><li><strong>Check system</strong>: Only YAML-only content reloads; code changes require restart</li><li><strong>Check permissions</strong>: Ensure file is saved and readable</li><li><strong>Check changes</strong>: Edit stats (health, cost); role changes require restart</li></ol><h3 id="f9-f10-not-responding" tabindex="-1">F9/F10 Not Responding <a class="header-anchor" href="#f9-f10-not-responding" aria-label="Permalink to &quot;F9/F10 Not Responding&quot;">​</a></h3><ol><li><strong>Check window focus</strong>: F9/F10 should work even unfocused, but fullscreen exclusive mode may block</li><li><strong>Check debounce</strong>: Wait 166ms between presses (10-frame cooldown)</li><li><strong>Check logs</strong>: Check <code>BepInEx/LogOutput.log</code> for KeyInputSystem errors</li></ol><hr><h2 id="version-history" tabindex="-1">Version History <a class="header-anchor" href="#version-history" aria-label="Permalink to &quot;Version History&quot;">​</a></h2><h3 id="v0-11-0-current" tabindex="-1">v0.11.0 (Current) <a class="header-anchor" href="#v0-11-0-current" aria-label="Permalink to &quot;v0.11.0 (Current)&quot;">​</a></h3><ul><li>Desktop Companion WinUI 3 app</li><li>F9/F10 key input refactored to RuntimeDriver</li><li>Asset swap Phase 2 (live entity updates)</li><li>678 tests passing</li></ul><h3 id="v0-10-0" tabindex="-1">v0.10.0 <a class="header-anchor" href="#v0-10-0" aria-label="Permalink to &quot;v0.10.0&quot;">​</a></h3><ul><li>Audio hot reload support</li><li>Companion file watcher integration</li><li>Bug fixes and optimizations</li></ul><h3 id="v0-9-0" tabindex="-1">v0.9.0 <a class="header-anchor" href="#v0-9-0" aria-label="Permalink to &quot;v0.9.0&quot;">​</a></h3><ul><li>Desktop Companion preview</li><li>Pack registry discovery improvements</li><li>MCP server enhancements</li></ul><h3 id="v0-8-0" tabindex="-1">v0.8.0 <a class="header-anchor" href="#v0-8-0" aria-label="Permalink to &quot;v0.8.0&quot;">​</a></h3><ul><li>4 additional Star Wars models imported</li><li>F10 mod menu improvements</li><li>Performance optimizations</li></ul><h3 id="v0-7-0" tabindex="-1">v0.7.0 <a class="header-anchor" href="#v0-7-0" aria-label="Permalink to &quot;v0.7.0&quot;">​</a></h3><ul><li>First visual asset imports</li><li>Asset swap Phase 1 and Phase 2</li><li>Hot reload for YAML content</li></ul><p>See <a href="/Dino/CHANGELOG">CHANGELOG.md</a> for full version history.</p><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><strong><a href="./../product-requirements-document">Product Requirements Document</a></strong>: High-level product goals and vision</li><li><strong><a href="./../QA_MATRIX">QA Matrix</a></strong>: Testing tiers and quality gates</li><li><strong><a href="./../guide/project-status">Project Status</a></strong>: Current release status and roadmap</li><li><strong><a href="./../../CONTRIBUTING">Contributing Guidelines</a></strong>: How to contribute to DINOForge</li></ul><hr><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><ul><li><strong>Discord</strong>: <a href="https://discord.gg/dino-forge" target="_blank" rel="noreferrer">DINOForge Community</a></li><li><strong>GitHub Issues</strong>: <a href="https://github.com/KooshaPari/Dino/issues" target="_blank" rel="noreferrer">Report bugs</a></li><li><strong>Discussions</strong>: <a href="https://github.com/KooshaPari/Dino/discussions" target="_blank" rel="noreferrer">Community Q&amp;A</a></li></ul><hr><p><strong>Last Updated</strong>: 2026-03-20 <strong>Status</strong>: Active Documentation <strong>Audience</strong>: All Users and Developers</p>`,67)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
